// Package asyncapigen writes Go DTOs from the schemas of an AsyncAPI
// document: one file per schema whose x-go-type names the package, the
// fields in the spec's order, omitempty on what the schema does not
// require. The spec is the source; the DTOs are never written by hand
// (docs/architecture/topics-on-nats.md).
package asyncapigen

import (
	"fmt"
	"go/format"
	"slices"
	"strings"
	"unicode"
)

// Generate returns the generated files of the package, by file name.
func Generate(spec []byte, source, goPackage string) (map[string][]byte, error) {
	root, err := parse(spec)
	if err != nil {
		return nil, err
	}
	if !strings.HasPrefix(root.get("asyncapi").str(), "3.") {
		return nil, fmt.Errorf("asyncapigen: %s is not an AsyncAPI 3 document", source)
	}
	schemas := root.get("components", "schemas")
	if schemas == nil {
		return nil, fmt.Errorf("asyncapigen: %s has no components.schemas", source)
	}
	types := map[string]string{}
	for _, name := range schemas.keys {
		if pkg, typ, ok := strings.Cut(schemas.fields[name].get("x-go-type").str(), "."); ok && pkg == goPackage {
			types[name] = typ
		}
	}
	files := map[string][]byte{}
	for _, name := range schemas.keys {
		typ, ok := types[name]
		if !ok {
			continue
		}
		code, err := structOf(schemas.fields[name], name, typ, types, source, goPackage)
		if err != nil {
			return nil, err
		}
		files[fileName(typ)] = code
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("asyncapigen: no schema of %s names x-go-type %s.<Type>", source, goPackage)
	}
	return files, nil
}

func structOf(schema *node, name, typ string, types map[string]string, source, goPackage string) ([]byte, error) {
	if t := schema.get("type").str(); t != "object" {
		return nil, fmt.Errorf("asyncapigen: schema %s is %q, not an object", name, t)
	}
	required := map[string]bool{}
	if list := schema.get("required"); list != nil {
		for _, item := range list.items {
			required[item.str()] = true
		}
	}
	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by asyncapigen from %s; DO NOT EDIT.\n\npackage %s\n\n", source, goPackage)
	comment(&b, "", "", typ+" is the schema "+name+" of the spec. "+schema.get("description").str())
	fmt.Fprintf(&b, "type %s struct {\n", typ)
	properties := schema.get("properties")
	if properties == nil || len(properties.keys) == 0 {
		return nil, fmt.Errorf("asyncapigen: schema %s has no properties", name)
	}
	for key := range required {
		if properties.get(key) == nil {
			return nil, fmt.Errorf("asyncapigen: schema %s requires %s, which it does not describe", name, key)
		}
	}
	for _, key := range properties.keys {
		property := properties.fields[key]
		goType, err := goTypeOf(property, types, name+"."+key)
		if err != nil {
			return nil, err
		}
		tag := key
		if !required[key] {
			tag += ",omitempty"
		}
		comment(&b, "\t", "", property.get("description").str())
		fmt.Fprintf(&b, "\t%s %s `json:%q`\n", fieldName(key), goType, tag)
	}
	b.WriteString("}\n")
	return format.Source([]byte(b.String()))
}

func goTypeOf(property *node, types map[string]string, where string) (string, error) {
	if ref := property.get("$ref").str(); ref != "" {
		target, ok := strings.CutPrefix(ref, "#/components/schemas/")
		if typ, known := types[target]; ok && known {
			return typ, nil
		}
		return "", fmt.Errorf("asyncapigen: %s refers to %s, which has no x-go-type in this package", where, ref)
	}
	switch property.get("type").str() {
	case "string":
		return "string", nil
	case "integer":
		return "int", nil
	case "number":
		return "float64", nil
	case "boolean":
		return "bool", nil
	case "array":
		item, err := goTypeOf(property.get("items"), types, where+"[]")
		if err != nil {
			return "", err
		}
		return "[]" + item, nil
	case "object":
		// An object the spec does not describe is free-form: whatever
		// JSON object the sender wrote. One it describes gets its own
		// schema and a $ref, so its fields are typed.
		if property.get("properties") == nil {
			return "map[string]any", nil
		}
	}
	return "", fmt.Errorf("asyncapigen: %s has type %q; give an object with properties its own schema and a $ref", where, property.get("type").str())
}

// comment writes a Go comment: the description, else the fallback.
func comment(b *strings.Builder, indent, fallback, description string) {
	text := strings.Join(strings.Fields(description), " ")
	if text == "" {
		text = fallback
	}
	if text == "" {
		return
	}
	line := indent + "//"
	for _, word := range strings.Fields(text) {
		if len(line)+1+len(word) > 76 && line != indent+"//" {
			b.WriteString(line + "\n")
			line = indent + "//"
		}
		line += " " + word
	}
	b.WriteString(line + "\n")
}

var initialisms = []string{"id", "url", "api", "json", "http", "uri"}

// fieldName turns a JSON name (camelCase or snake_case) into an
// exported Go name: traceId → TraceID, order_id → OrderID.
func fieldName(key string) string {
	var words []string
	start := 0
	for i, r := range key {
		switch {
		case r == '_':
			words = append(words, key[start:i])
			start = i + 1
		case i > start && unicode.IsUpper(r):
			words = append(words, key[start:i])
			start = i
		}
	}
	words = append(words, key[start:])
	var b strings.Builder
	for _, word := range words {
		if word == "" {
			continue
		}
		if slices.Contains(initialisms, strings.ToLower(word)) {
			b.WriteString(strings.ToUpper(word))
			continue
		}
		b.WriteString(strings.ToUpper(word[:1]) + word[1:])
	}
	return b.String()
}

// fileName is the generated file of a type: DataDTO → data_dto_gen.go.
func fileName(typ string) string {
	var b strings.Builder
	runes := []rune(typ)
	for i, r := range runes {
		if i > 0 && unicode.IsUpper(r) && (unicode.IsLower(runes[i-1]) || (i+1 < len(runes) && unicode.IsLower(runes[i+1]))) {
			b.WriteByte('_')
		}
		b.WriteRune(unicode.ToLower(r))
	}
	return b.String() + "_gen.go"
}
